const debug=!1;class App{elements={"app-shopping":document.querySelector(`[fw-id="app-shopping"]`),"app-starred":document.querySelector(`[fw-id="app-starred"]`),"app-monitoring":document.querySelector(`[fw-id="app-monitoring"]`),"app-customers":document.querySelector(`[fw-id="app-customers"]`),"app-logo":document.querySelector(`[fw-id="app-logo"]`),main_settings:document.querySelector(`[fw-id="main_settings"]`),"app-user-settings":document.querySelector(`[fw-id="app-user-settings"]`),app_content:document.querySelector(`[fw-id="app_content"]`),"app-style":document.querySelector(`[fw-id="app-style"]`),da_app:document.querySelector(`[fw-id="da_app"]`),"start-content":document.querySelector(`[fw-id="start-content"]`)};instances={AppRouter:null};constructor(){document.body.addEventListener("keydown",e=>{e.ctrlKey&&"r"==e.key&&(e.stopPropagation(),e.preventDefault(),Lobby.post("AppRouter/Navigate",{where:"DashboardLayout1"},e=>{resolve()}))}),this.#e();this.instances.AppRouter=new AppRouter(this.elements.app_content,{AndroidViewAccount:AndroidViewAccount,AndroidViewAnalytics:AndroidViewAnalytics,AndroidViewHome:AndroidViewHome,AndroidViewInventory:AndroidViewInventory,UserSettings:e=>new Settings({...e,scope:"UserSettings"}),Settings:Settings}),AppStatus.displayVersion()}async#e(){}async goGoTo(e){this.instances.AppRouter.navigate(e)}onChangeAppearance(e){this.fwInstanceReference.elements.da_app.classList.toggle("app-grid-expanded")}onClickLogo(e){const t=this.fwInstanceReference;t.elements.da_app.innerText="",t.elements.da_app.appendChild(t.elements["start-content"])}}